    def rail_fence_cipher(self, plain_text, rails):
        """
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, str.
        :return: The ciphertext, str.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'

        """
        if rails <= 1 or len(plain_text) == 0:
            return plain_text

        # Create rails to store characters
        fence = [[] for _ in range(rails)]

        # Track current rail and direction
        rail_idx = 0
        direction = 1

        # Place each character in the appropriate rail following zigzag pattern
        for char in plain_text:
            fence[rail_idx].append(char)

            # Change direction at top and bottom rails
            if rail_idx == 0:
                direction = 1
            elif rail_idx == rails - 1:
                direction = -1

            rail_idx += direction

        # Concatenate all rails to get ciphertext
        return ''.join(''.join(rail) for rail in fence)
